import{_ as n,o as i,c as e,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Pertanyaan yang Sering Diajukan FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"id/0096-常见问题FAQ.md","filePath":"id/0096-常见问题FAQ.md"}'),t={name:"id/0096-常见问题FAQ.md"};function r(u,a,k,d,m,g){return i(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="pertanyaan-yang-sering-diajukan-faq" tabindex="-1">Pertanyaan yang Sering Diajukan FAQ <a class="header-anchor" href="#pertanyaan-yang-sering-diajukan-faq" aria-label="Permalink to &quot;Pertanyaan yang Sering Diajukan FAQ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>96</td></tr><tr><td>Modul</td><td>Lampiran dan Materi Referensi</td></tr><tr><td>Kata kunci utama</td><td>pertanyaan umum, FAQ, jawaban keraguan, klarifikasi pengaturan, panduan pemula</td></tr></tbody></table><h2 id="_1-deskripsi" tabindex="-1">1. Deskripsi <a class="header-anchor" href="#_1-deskripsi" aria-label="Permalink to &quot;1. Deskripsi&quot;">​</a></h2><p>Dokumen ini berisi pertanyaan yang sering diajukan dan jawaban tentang sistem pengaturan Peradaban Simbiosis Jangkar, disusun berdasarkan tema. Pertanyaan-pertanyaan mencakup berbagai aspek seperti konsep inti pandangan dunia, sistem kultivasi, institusi sosial, sistem hukum, interaksi antar bidang, dan aturan waktu. Tujuan dokumen ini adalah memberikan panduan pemula yang cepat bagi pembaca yang pertama kali berhubungan dengan pengaturan Peradaban Simbiosis Jangkar, sekaligus memberikan jawaban otoritatif untuk keraguan umum bagi peneliti mendalam. Dokumen ini adalah dokumen pembaruan dinamis; dengan umpan balik pembaca, tanya jawab baru akan terus ditambahkan.</p><h2 id="_2-pandangan-dunia-dan-konsep-inti" tabindex="-1">2. Pandangan Dunia dan Konsep Inti <a class="header-anchor" href="#_2-pandangan-dunia-dan-konsep-inti" aria-label="Permalink to &quot;2. Pandangan Dunia dan Konsep Inti&quot;">​</a></h2><p><strong>Q1: Apa klaim inti Peradaban Simbiosis Jangkar?</strong> A: Klaim inti Peradaban Simbiosis Jangkar adalah &quot;anti-penjarahan, advokasi simbiosis&quot;. Secara spesifik, ia menentang sistem kultivasi tipe penjarahan yang mengorbankan energi, keberuntungan, bahkan asal-usul yang lemah dengan cara melahap, dan menganjurkan evolusi bersama melalui kerja sama simbiosis. Konsep inti peradaban adalah &quot;mengembalikan hak pilihan nasib dan evolusi kepada semua makhluk&quot;, dan kebijakan dasarnya adalah &quot;lebih banyak kerja lebih banyak hasil, tumbuh mandiri, semua orang punya jalan, semua ras maju bersama&quot;.</p><p><strong>Q2: Apa arti prinsip &quot;berbasis realitas&quot;?</strong> A: &quot;Berbasis realitas&quot; adalah salah satu posisi fundamental Peradaban Simbiosis Jangkar, yang menunjukkan bahwa dunia nyata adalah satu-satunya dunia yang nyata, dan dunia novel adalah eksperimen pikiran palsu. Dalam konstruksi pengaturan, bagian fiksi yang tidak cukup dilengkapi dengan realitas, dan hal-hal yang tidak ada dalam realitas ditingkatkan dan diciptakan berdasarkan hukum objektif. Prinsip ini menjamin konsistensi logis dan persepsi nyata dari sistem pengaturan, menghindari keruntuhan pengaturan yang disebabkan oleh imajinasi murni.</p><p><strong>Q3: Apa hubungan antara Hengyuanzhou dan alam semesta?</strong> A: Nama lengkap Hengyuanzhou adalah &quot;Wan Ling Heng Mao Ben Yuan Zhou&quot;, yang merupakan seluruh alam semesta yang dihuni dan diperintah oleh Peradaban Simbiosis Jangkar. Ini bukan alam semesta fisik tunggal dalam arti umum, melainkan keberadaan majemuk yang terdiri dari empat lapisan: bidang material, lapisan energi, domain kesadaran, dan jaringan hukum. Dapat dipahami bahwa Hengyuanzhou adalah sistem alam semesta super yang berisi banyak bidang dan menggunakan mekanisme jangkar sebagai sarana regulasi inti.</p><h2 id="_3-sistem-kultivasi" tabindex="-1">3. Sistem Kultivasi <a class="header-anchor" href="#_3-sistem-kultivasi" aria-label="Permalink to &quot;3. Sistem Kultivasi&quot;">​</a></h2><p><strong>Q4: Dari mana datangnya tiga ratus set sistem kultivasi asal?</strong> A: Tiga ratus set sistem bukan metode kultivasi yang dibuat-buat secara artifisial, melainkan jalur kultivasi ortodoks yang diekstrak langsung dari hukum asal alam semesta dan diverifikasi oleh jangkar. Selama periode pembentukan sistem simbiosis, tim yang dipimpin oleh &quot;San Baishi&quot; melakukan penggalian dan penyusunan sistematis terhadap hukum alam semesta, dan akhirnya merangkum tiga ratus set sistem kultivasi yang mencakup semua dimensi evolusi. Sistem-sistem ini dibagi menjadi enam kategori: kelas deduksi asal, kelas siklus kehidupan, kelas hukum ruang, kelas peningkatan dimensi kesadaran, kelas jaringan simbiosis, dan kelas teknik terapan, dengan lima puluh set di setiap kategori.</p><p><strong>Q5: Mengapa tiga set sistem pertama disebut &quot;tiga dasar asal&quot;?</strong> A: Tiga set sistem pertama — iterasi deduksi (set ke-1), siklus kehidupan (set ke-2), dan manajemen hukum ruang (set ke-3) — adalah dasar kultivasi dari semua sistem lainnya. Sistem iterasi deduksi memberikan dasar kebijaksanaan dan metodologi, sistem siklus kehidupan memberikan dasar energi kehidupan, dan sistem manajemen hukum ruang memberikan dasar operasi ruang dan hukum. Disarankan agar kultivator dari sistem lain mana pun mempraktikkan setidaknya satu dari tiga dasar asal terlebih dahulu, untuk membangun fondasi evolusi yang kokoh.</p><p><strong>Q6: Apa itu buah Bei Zeng? Apa hubungannya dengan One Piece?</strong> A: Buah Bei Zeng adalah salah satu &quot;buff awal&quot; Peradaban Simbiosis Jangkar, yang berasal dari pengaturan buah Bei Zeng di dunia One Piece. Di Hengyuanzhou, buah Bei Zeng diterapkan secara teknologi, mampu meningkatkan kemampuan deduksi kultivator hingga seratus kali lipat, dan merupakan alat bantu inti dari sistem iterasi deduksi. Pengaturan ini mencerminkan prinsip &quot;melengkapi fiksi yang tidak cukup dengan realitas, meningkatkan dan menciptakan apa yang tidak ada dalam realitas berdasarkan hukum&quot; — memasukkan pengaturan menarik dari karya fiksi ke dalam sistem teknologi peradaban simbiosis setelah transformasi hukum.</p><p><strong>Q7: Apa strategi aktivasi 20%? Mengapa 20%?</strong> A: Strategi aktivasi 20% adalah tujuan strategis bertahap Peradaban Simbiosis Jangkar, yang bertujuan untuk mengaktifkan 20% dari semua makhluk di seluruh alam semesta menjadi yang terkuat di bidang pada tahap awal. Pemilihan proporsi 20% didasarkan pada analisis dinamika jaringan simbiosis — ketika 20% node dalam jaringan mencapai keadaan energi tinggi, efek resonansi keseluruhan jaringan memicu titik kritis, yang mendorong evolusi dipercepat dari 80% node yang tersisa. 20% yang terkuat di bidang ini akan bertindak sebagai kekuatan tulang punggung, memainkan peran inti dalam pemeliharaan jangkar, bimbingan mentor, dan pembangunan peradaban.</p><h2 id="_4-institusi-sosial-dan-hukum" tabindex="-1">4. Institusi Sosial dan Hukum <a class="header-anchor" href="#_4-institusi-sosial-dan-hukum" aria-label="Permalink to &quot;4. Institusi Sosial dan Hukum&quot;">​</a></h2><p><strong>Q8: Apa lima jenis klasifikasi peradaban simbiosis?</strong> A: Lima jenis klasifikasi peradaban simbiosis adalah lima jenis masyarakat simbiosis yang dibagi berdasarkan karakteristik peradaban dunia nyata, termasuk: tipe intensif Asia Timur (dicirikan oleh organisasi efisien dan kolektivisme), tipe kesejahteraan Nordik (dicirikan oleh kesejahteraan tinggi dan kesetaraan sosial), tipe plural Amerika Utara (dicirikan oleh multikulturalisme dan vitalitas inovatif), tipe sosial Eropa kontinental (dicirikan oleh ekonomi pasar sosial dan partisipasi tenaga kerja), dan tipe pengejaran berkembang (dicirikan oleh perkembangan cepat dan keuntungan terlambat). Lima jenis klasifikasi ini bukan klasifikasi yang saling eksklusif, melainkan model referensi yang dapat saling belajar dan berkembang secara terintegrasi.</p><p><strong>Q9: Bagaimana mekanisme kontrak produksi bersama bekerja?</strong> A: Mekanisme kontrak produksi bersama adalah sistem alokasi sumber daya inti Peradaban Simbiosis Jangkar, yang terinspirasi oleh sistem tanggung jawab kontrak produksi bersama keluarga di dunia nyata. Cara kerjanya adalah: mengalokasikan sumber daya kultivasi alam semesta kepada individu atau kelompok dengan cara &quot;kontrak&quot;, dan kontraktor mendapatkan hak penggunaan dan hak manfaat dari sumber daya melalui kerja dan kontribusi. Lebih banyak kerja lebih banyak hasil, dan semakin besar kontribusi semakin banyak sumber daya yang diperoleh. Mekanisme ini tidak hanya menjamin alokasi sumber daya yang adil, tetapi juga merangsang antusiasme kerja individu, mewujudkan kesatuan keadilan dan efisiensi.</p><p><strong>Q10: Apa hubungan antara Konstitusi Simbiosis dan hukum umum?</strong> A: Konstitusi Simbiosis adalah hukum fundamental Peradaban Simbiosis Jangkar, dengan kekuatan hukum tertinggi. Semua hukum, peraturan administratif, dan peraturan lokal tidak boleh bertentangan dengan Konstitusi. Hukum Kerja Simbiosis, Hukum Perlindungan Konsumen, dan lima hukum pendukung pendidikan, kesehatan, perumahan, lingkungan, dan antimonopoli semuanya adalah hukum sektoral yang disusun berdasarkan Konstitusi Simbiosis sebagai dasar legislatif, bertanggung jawab untuk mewujudkan ketentuan prinsipil Konstitusi menjadi konkret dan dapat dioperasikan. Pengadilan Simbiosis berhak melakukan tinjauan inkonstitusional terhadap hukum yang melanggar Konstitusi dan menyatakannya tidak sah.</p><h2 id="_5-interaksi-antar-bidang" tabindex="-1">5. Interaksi Antar Bidang <a class="header-anchor" href="#_5-interaksi-antar-bidang" aria-label="Permalink to &quot;5. Interaksi Antar Bidang&quot;">​</a></h2><p><strong>Q11: Apa rencana arkeologi &quot;cermin salinan + ruang terisolasi + hanya mengembalikan pengetahuan&quot;?</strong> A: Ini adalah rencana standar untuk arkeologi antar bidang dan penelusuran waktu Peradaban Simbiosis Jangkar, yang terdiri dari tiga elemen inti:</p><ol><li><strong>Cermin salinan</strong>: melakukan salinan lengkap 1:1 dari target arkeologi tanpa menyentuh objek asli, dan proses penyalinan tidak mengubah keadaan apa pun dari objek asli.</li><li><strong>Ruang terisolasi</strong>: salinan dihasilkan di ruang independen yang sepenuhnya terisolasi dari target, dan arkeolog melakukan semua operasi penelitian di dalam ruang terisolasi.</li><li><strong>Hanya mengembalikan pengetahuan</strong>: setelah arkeologi selesai, hanya pengetahuan dan informasi abstrak yang dapat dikembalikan; materi dan energi salinan harus dihancurkan di dalam ruang terisolasi, dan tidak boleh dibawa kembali ke bidang sendiri. Rencana ini menjamin nol intervensi dari proses arkeologi terhadap bidang target atau periode target, dan sekaligus mencegah polusi antar bidang.</li></ol><p><strong>Q12: Mengapa harus mengikuti prinsip &quot;pertama mengamati, kemudian intervensi terbatas&quot;?</strong> A: Konsep inti dari prinsip ini adalah &quot;kerendahan hati kognitif&quot; — bahkan yang terkuat di bidang pun tidak dapat menguasai sepenuhnya semua hubungan kausal dari satu simpul waktu atau satu peradaban bidang. Intervensi langsung apa pun terhadap masa lalu atau bidang lain dapat memicu reaksi berantai kausal yang tidak terduga. Oleh karena itu, harus terlebih dahulu melakukan pengamatan komprehensif dengan sikap paling hati-hati, dan hanya di bawah premis data pengamatan yang cukup dan penilaian risiko yang jelas, intervensi terbatas dengan cakupan dan tingkat yang dibatasi secara ketat diizinkan. Prinsip ini adalah jaminan fundamental untuk keamanan operasi penelusuran waktu dan antar bidang.</p><p><strong>Q13: Kondisi apa yang diperlukan untuk perjalanan antar bidang?</strong> A: Perjalanan antar bidang memerlukan pemenuhan kondisi berikut: pertama, pelancong harus memiliki kultivasi di atas tahap ketiga (Hua Kong Jing) dari sistem manajemen hukum ruang, atau membawa kendaraan perjalanan yang memenuhi standar; kedua, harus mendapatkan izin perjalanan tingkat相应 yang dikeluarkan oleh Biro Manajemen Bidang (tingkat A pengamatan arkeologi, tingkat B pertukaran akademik, tingkat C kerja sama sumber daya, tingkat D intervensi darurat); ketiga, baik titik awal maupun titik akhir perjalanan harus memiliki jangkar untuk kalibrasi koordinat; keempat, harus menyelesaikan prosedur pemurnian tiga tingkat (pemurnian biologis, pemurnian energi, pemurnian kesadaran); kelima, energi perjalanan harus dibawa sendiri, dan dilarang mengambil dari bidang target.</p><h2 id="_6-aturan-waktu" tabindex="-1">6. Aturan Waktu <a class="header-anchor" href="#_6-aturan-waktu" aria-label="Permalink to &quot;6. Aturan Waktu&quot;">​</a></h2><p><strong>Q14: Apa perbedaan antara penelusuran waktu dan perjalanan waktu?</strong> A: Dalam pengaturan Hengyuanzhou, penelusuran waktu tidak sama dengan perjalanan waktu. Penelusur waktu tidak memasuki masa lalu dalam bentuk material lengkap, melainkan tiba di simpul waktu target dalam bentuk proyeksi kesadaran atau paket informasi. Keberadaan penelusur selama periode masa lalu adalah &quot;semi-transparan&quot; — dapat mengamati, tetapi kemampuan interaksi fisik sangat dibatasi. Desain ini sendiri merupakan bagian dari mekanisme keamanan penelusuran waktu, yang mengurangi kemungkinan intervensi fisik penelusur terhadap masa lalu.</p><p><strong>Q15: Apa jenis paradoks waktu? Bagaimana mencegahnya?</strong> A: Paradoks waktu dibagi menjadi empat kategori utama: paradoks kakek (perilaku penelusur menyebabkan kondisi kausal keberadaannya sendiri dihilangkan), paradoks informasi (informasi yang dikembalikan dari masa depan ke masa lalu membentuk siklus informasi tanpa sumber), paradoks ontologis (interaksi penelusur dengan dirinya sendiri di masa lalu menyebabkan kebingungan kesadaran ontologis), dan paradoks peristiwa (penelusur mengubah peristiwa sejarah penting, menyebabkan rekonstruksi rantai kausal). Mekanisme pencegahan meliputi: penilaian kausal sebelum penelusuran dan isolasi kausal penelusur sebelum peristiwa, sistem daftar putih perilaku intervensi, pemantauan kausal waktu nyata dan respons darurat tiga tingkat selama peristiwa, perbaikan kausal dan audit setelah peristiwa. Tujuan dari seluruh sistem pencegahan adalah menghilangkan paradoks dalam keadaan embrio.</p><h2 id="_7-kehidupan-dan-ras" tabindex="-1">7. Kehidupan dan Ras <a class="header-anchor" href="#_7-kehidupan-dan-ras" aria-label="Permalink to &quot;7. Kehidupan dan Ras&quot;">​</a></h2><p><strong>Q16: Apa itu kehidupan aneh dan energi aneh?</strong> A: Kehidupan aneh merujuk pada bentuk kehidupan dengan bentuk keberadaan khusus yang tidak sesuai dengan definisi kehidupan konvensional, seperti kehidupan energi murni, kehidupan bentuk kesadaran, kehidupan mekanis, dll. Energi aneh merujuk pada bentuk energi dengan atribut dan pola perilaku khusus yang tidak sesuai dengan klasifikasi energi konvensional, seperti energi hukum, energi kesadaran, energi kausal, dll. Untuk dua jenis keberadaan khusus ini, Peradaban Simbiosis Jangkar telah menetapkan tiga jenis prosedur penanganan standar (identifikasi dan klasifikasi, penilaian dan kontrol, fusi dan simbiosis), memastikan bahwa mereka dikelola dengan baik dan dimanfaatkan secara wajar dalam kerangka peradaban simbiosis.</p><p><strong>Q17: Apa itu tubuh pengganti kegelapan? Apa itu etika jiwa ganda?</strong> A: Tubuh pengganti kegelapan adalah bentuk kehidupan khusus, di mana ada dua jiwa secara bersamaan di dalam tubuh — biasanya jiwa asli dan jiwa &quot;pengganti&quot; asing. Keadaan ini menimbulkan masalah etika yang kompleks: kedua jiwa memiliki hak dan kepribadian masing-masing, dan tidak dapat secara sederhana menghilangkan salah satunya. Inti dari kode etik jiwa ganda adalah menghormati hak masing-masing dari kedua jiwa, melarang fusi paksa atau penghapusan sepihak. Berdasarkan keadaan spesifik, tubuh pengganti kegelapan dibagi menjadi empat cabang, masing-masing mengadopsi rencana penanganan yang berbeda: tipe koeksistensi (kedua jiwa hidup berdampingan secara harmonis), tipe bergantian (kedua jiwa mengendalikan tubuh secara bergantian), tipe pemisahan (kedua jiwa dipisahkan ke wadah yang berbeda melalui sarana teknis), dan tipe fusi (fusi mendalam menjadi jiwa baru berdasarkan kesukarelaan kedua belah pihak).</p><h2 id="_8-metodologi-pengaturan" tabindex="-1">8. Metodologi Pengaturan <a class="header-anchor" href="#_8-metodologi-pengaturan" aria-label="Permalink to &quot;8. Metodologi Pengaturan&quot;">​</a></h2><p><strong>Q18: Apa perbedaan antara sistem pengaturan ini dan pengaturan novel web umum?</strong> A: Perbedaan terbesar dari sistem pengaturan Peradaban Simbiosis Jangkar terletak pada posisi intinya yang &quot;anti-penjarahan&quot;. Pengaturan novel web umum biasanya berpusat pada pertumbuhan pribadi dan peningkatan kekuatan protagonis, dan sistem kultivasinya pada dasarnya adalah tipe penjarahan — protagonis menjadi kuat dengan melahap, bertarung, dan merebut sumber daya. Sebaliknya, Peradaban Simbiosis Jangkar pada dasarnya menentang model ini, dan menganjurkan evolusi bersama semua ras melalui kerja sama simbiosis. Selain itu, sistem pengaturan ini menekankan &quot;berbasis realitas&quot;, dan semua pengaturan berusaha untuk konsisten secara logis dan sesuai dengan hukum objektif, menghindari imajinasi murni dan keruntuhan pengaturan.</p><p><strong>Q19: Apa secara spesifik jalur peningkatan dimensi empat tahap?</strong> A: Jalur peningkatan dimensi empat tahap adalah rute strategis untuk peningkatan dimensi keseluruhan alam semesta Hengyuanzhou:</p><ol><li><strong>Fondasi nyata</strong>: membangun sistem sosial simbiosis di bidang material, menghilangkan akar penjarahan, menyelesaikan pembangunan fondasi institusional peradaban.</li><li><strong>Pemberdayaan teknologi</strong>: menggabungkan hukum kultivasi dengan teknik teknologi, mengurangi ambang evolusi, mewujudkan lompatan produktivitas.</li><li><strong>Evolusi kesadaran</strong>: mendorong migrasi bentuk kehidupan ke domain kesadaran, mewujudkan simbiosis dan sublimasi di tingkat spiritual.</li><li><strong>Simbiosis antarbintang</strong>: membangun jaringan jangkar lengkap antar bidang dan antarbintang, menyelesaikan peningkatan dimensi keseluruhan alam semesta. Saat ini, Hengyuanzhou berada dalam periode kritis transisi dari tahap pertama ke tahap kedua.</li></ol><p><strong>Q20: Bagaimana cara berpartisipasi dalam ekspansi sistem pengaturan ini?</strong> A: Sistem pengaturan Peradaban Simbiosis Jangkar adalah sistem terbuka yang terus berkembang. Siapa pun dapat melakukan kreasi ekspansi berdasarkan kerangka pengaturan yang ada, termasuk tetapi tidak terbatas pada: merinci metode spesifik dari sistem kultivasi tertentu, menciptakan budaya dan sejarah dari ras tertentu, merancang bentuk peradaban dari bidang tertentu, menulis peristiwa mendetail dari periode sejarah tertentu, mengembangkan teknologi baru dan skenario aplikasi. Pengaturan ekspansi harus mengikuti prinsip &quot;berbasis realitas, peningkatan sesuai hukum&quot;, memastikan konsistensi logis dengan pengaturan yang ada. Pengaturan ekspansi yang sangat baik dapat dimasukkan ke dalam sistem pengaturan formal setelah ditinjau.</p><h2 id="kesimpulan" tabindex="-1">Kesimpulan <a class="header-anchor" href="#kesimpulan" aria-label="Permalink to &quot;Kesimpulan&quot;">​</a></h2><p>FAQ pertanyaan yang sering diajukan adalah pintu masuk cepat ke dunia pengaturan Peradaban Simbiosis Jangkar. Melalui dua puluh tanya jawab ini, pembaca dapat dengan cepat memahami konsep inti, mekanisme kunci, dan kerangka dasar dari sistem pengaturan. Tentu saja, FAQ tidak dapat mencakup semua detail dari sistem pengaturan, dan pemahaman mendalam masih memerlukan pembacaan dokumen khusus dari setiap modul. Seiring dengan pengayaan berkelanjutan dari sistem pengaturan, FAQ ini juga akan terus diperbarui, selalu berfungsi sebagai referensi yang andal untuk pemula dan klarifikasi keraguan pembaca.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>00-Gambaran Umum Alam Semesta Hengyuanzhou</li><li>90-Kamus Istilah</li><li>98-Daftar Saran Ekspansi Pengaturan</li></ul>',37)])])}const o=n(t,[["render",r]]);export{p as __pageData,o as default};
